return $input.all().map(item => {
  const tweet = item.json;
  let text = (tweet.full_text || tweet.text || "").toLowerCase();

  // 1. Kamus Sentimen
  const keywordMarah = ["mahal", "naik", "susah", "menyusahkan", "tolak", "gila", "parah", "beban", "ribet", "perang", "hancur"];
  const keywordSetuju = ["setuju", "dukung", "bagus", "tepat sasaran", "adil", "wajar", "mantap"];
  const keywordPasrah = ["pasrah", "terserah", "mau gimana", "ikut aja", "ya udahlah", "nasib"];

  // 2. Logika Penentuan Kategori & Skor
  let kategori = "PASRAH";
  let skor = 0.0;

  if (keywordMarah.some(word => text.includes(word))) {
    kategori = "MARAH"; skor = -1.0;
  } else if (keywordSetuju.some(word => text.includes(word))) {
    kategori = "SETUJU"; skor = 1.0;
  } else if (keywordPasrah.some(word => text.includes(word))) {
    kategori = "PASRAH"; skor = 0.0;
  }

  // 3. Logika Ekstraksi Tokoh menggunakan RegEx (\b memastikan kata berdiri sendiri)
  let tokoh = [];

  if (/\b(trump|amerika|usa|as)\b/.test(text)) {
      tokoh.push("Trump");
  }
  if (/\b(netanyahu|israel|zionis)\b/.test(text)) {
      tokoh.push("Netanyahu");
  }
  if (/\b(khamenei|iran)\b/.test(text)) {
      tokoh.push("Khamenei");
  }

  // 4. Masukkan semua hasil ke dalam JSON
  item.json.kategori_hasil_sortir = kategori;
  item.json.skor_hasil_sortir = skor;
  item.json.tokoh_terkait = tokoh.length > 0 ? tokoh.join(", ") : null;

  return item;
});

// Ambil data asli dari node sebelum AI (pastikan nama node-nya 'Loop')
const originalData = $('Loop').all(); 

return $input.all().map((item, index) => {
  let aiResponse = "";

  // 1. TARIK TEKS MENGGUNAKAN PATH YANG BENAR
  try {
      aiResponse = item.json.candidates[0].content.parts[0].text;
  } catch (e) {
      aiResponse = "";
  }

  let parsedData = {};

  try {
    // 2. Bersihkan markdown jika Gemini sesekali iseng nambahin ```json
    let cleanString = aiResponse.replace(/```json/g, '').replace(/```/g, '').trim();

    // 3. Parse JSON-nya
    parsedData = JSON.parse(cleanString);

    // Kalau ternyata jadi array, ambil yang pertama
    if (Array.isArray(parsedData)) {
        parsedData = parsedData[0] || {}; 
    }
  } catch (error) {
    // Fallback kalau JSON-nya cacat
    parsedData = { kategori_hasil_sortir: "PASRAH", tokoh_terkait: null };
  }

  // 4. Tarik tweet asli yang sesuai urutannya
  let originalTweet = {};
  if (originalData && originalData[index]) {
      originalTweet = originalData[index].json;
  }

  // 5. Filter tokoh persis seperti output AI
  let tokohAI = parsedData.tokoh_terkait;

  // Bersihkan teks "null" bohongan biar jadi NULL beneran di Supabase
  if (tokohAI === "null" || tokohAI === "" || tokohAI === "Umum" || typeof tokohAI === 'undefined') {
      tokohAI = null;
  }

  return {
    json: {
      ...originalTweet,
      kategori_hasil_sortir: parsedData.kategori_hasil_sortir || "PASRAH",
      tokoh_terkait: tokohAI
    }
  };
});
